/** The seat count every plan check compares against. */
export async function countActiveMembers(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertMember(
  orgId: OrgId,
  userId: UserId,
  role: Role,
  invitedBy: UserId | null,
): Promise<Member> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(members)
    .values({
      id: newId(),
      orgId,
      userId,
      role,
      status: "active",
      invitedBy,
      joinedAt: stamp,
      lastSeenAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMember(row);
