/**
 * Extracts `@handle` mentions from comment bodies and resolves them to member
 * ids.
 *
 * A handle is the local part of a member's email address, lowercased — that
 * is what the comment composer autocompletes and what `CommentService` feeds
 * to the notification fan-out, so extraction and resolution must agree
 * exactly. Mentions inside code spans and fenced blocks are ignored.
 */
import type { UserId } from "@/types/common";
import type { MemberWithUser } from "@/types/member";

/** `@` must start the line or follow whitespace/punctuation, never an email. */
const MENTION_PATTERN = /(^|[\s(<[])@([a-z0-9][a-z0-9._-]{0,38}[a-z0-9])/gi;

function withoutCode(body: string): string {
  return body.replace(/```[\s\S]*?```/g, " ").replace(/`[^`]*`/g, " ");
}

/** The handle Taskflow addresses a member by, derived from their email. */
export function handleOf(member: MemberWithUser): string {
  return (member.user.email.split("@")[0] ?? "").toLowerCase();
}

/** Every distinct handle mentioned, in first-appearance order. */
export function extractMentions(body: string): readonly string[] {
  const seen = new Set<string>();
  const handles: string[] = [];

  for (const match of withoutCode(body).matchAll(MENTION_PATTERN)) {
    const handle = (match[2] ?? "").toLowerCase();
    if (handle === "" || seen.has(handle)) continue;
    seen.add(handle);
    handles.push(handle);
  }

  return handles;
}

/**
 * Maps the mentions in `body` onto the ids of members who actually exist in
 * the organization. Unknown handles are silently dropped — a typo must never
 * fail the comment write.
 */
export function resolveMentions(
  body: string,
  members: readonly MemberWithUser[],
): readonly UserId[] {
  const byHandle = new Map<string, UserId>();
  for (const member of members) {
    byHandle.set(handleOf(member), member.userId);
  }

  const resolved: UserId[] = [];
  const seen = new Set<UserId>();
  for (const handle of extractMentions(body)) {
    const userId = byHandle.get(handle);
    if (userId === undefined || seen.has(userId)) continue;
    seen.add(userId);
    resolved.push(userId);
  }

  return resolved;
}

/** Wraps every mention in a span so the comment renderer can style it. */
export function highlightMentions(body: string): string {
  return body.replace(
    MENTION_PATTERN,
    (_match, prefix: string, handle: string) =>
      `${prefix}<span class="mention">@${handle}</span>`,
  );
}
/**
 * Thin wrappers turning a Zod parse into an `AppErrorShape` without throwing.
 *
 * Server Actions parse `FormData` with `safeParse()` so a validation failure
 * comes back as a `Result` the form layer can render; pages parse
 * `searchParams` with `parseSearchParams()`, which never fails because a
 * hand-edited URL must not produce an error boundary.
 */
import type { Result } from "@/types/api";
import { err, ok } from "@/types/api";
import type { ZodType } from "zod";
import { fieldErrorsFromZod } from "./errors";

/** Parses without throwing; failures carry Zod's field errors verbatim. */
export function safeParse<TSchema extends ZodType>(
  schema: TSchema,
  raw: unknown,
): Result<unknown> {
  const parsed = schema.safeParse(raw);
  if (parsed.success) return ok<unknown>(parsed.data);

  return err<unknown>({
    code: "validation_failed",
    message: "Please correct the highlighted fields.",
    fieldErrors: fieldErrorsFromZod(parsed.error),
  });
}

/**
 * Normalises a Next `searchParams` record (values may be repeated, and are
 * always strings) and parses it. Because the pagination and sort schemas use
 * `.catch()` defaults, a malformed query string degrades to the defaults
 * rather than failing the render; a schema without catches will still throw,
 * which is the correct signal that the route needs one.
 */
export function parseSearchParams<TSchema extends ZodType>(
  schema: TSchema,
  raw: Readonly<Record<string, string | string[] | undefined>>,
): unknown {
  const normalized: Record<string, string | string[]> = {};
  for (const [key, value] of Object.entries(raw)) {
    if (value === undefined) continue;
    normalized[key] = value;
  }

  return schema.parse(normalized);
}
/**
 * Applies the drizzle-kit migrations in ./drizzle to the SQLite file. Run via `pnpm db:migrate`.
 */
import { existsSync, mkdirSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import Database from "better-sqlite3";

const DEFAULT_DB_PATH = "./data/taskflow.db";
const MIGRATIONS_DIR = "./drizzle";

/**
 * Statements that bring an empty database up to the current schema.
 *
 * `drizzle-kit generate` writes SQL into `./drizzle`, and when that directory
 * exists it is authoritative. It is not checked in — the corpus has to migrate
 * offline from a clean clone — so this is the fallback "push" path, equivalent
 * to `drizzle-kit push` and kept in step with `src/server/db/schema/**`.
 */
const SCHEMA_STATEMENTS: readonly string[] = [
  `CREATE TABLE IF NOT EXISTS users (
     id TEXT PRIMARY KEY NOT NULL,
     email TEXT NOT NULL,
     name TEXT NOT NULL,
     password_hash TEXT NOT NULL,
     avatar_url TEXT,
     timezone TEXT NOT NULL DEFAULT 'UTC',
     email_verified_at TEXT,
     created_at TEXT NOT NULL,
     updated_at TEXT NOT NULL
   )`,
  `CREATE UNIQUE INDEX IF NOT EXISTS users_email_idx ON users (email)`,
  `CREATE TABLE IF NOT EXISTS sessions (
     id TEXT PRIMARY KEY NOT NULL,
     user_id TEXT NOT NULL,
     active_org_id TEXT,
     token_hash TEXT NOT NULL,
     expires_at TEXT NOT NULL,
     created_at TEXT NOT NULL,
     updated_at TEXT NOT NULL
   )`,
  `CREATE UNIQUE INDEX IF NOT EXISTS sessions_token_idx ON sessions (token_hash)`,
  `CREATE TABLE IF NOT EXISTS password_reset_tokens (
     id TEXT PRIMARY KEY NOT NULL,
     user_id TEXT NOT NULL,
     token_hash TEXT NOT NULL,
     expires_at TEXT NOT NULL,
     used_at TEXT,
     created_at TEXT NOT NULL,
     updated_at TEXT NOT NULL
   )`,
  `CREATE TABLE IF NOT EXISTS organizations (
     id TEXT PRIMARY KEY NOT NULL,
     name TEXT NOT NULL,
     slug TEXT NOT NULL,
     owner_id TEXT NOT NULL,
     plan TEXT NOT NULL DEFAULT 'free',
     logo_url TEXT,
     trial_ends_at TEXT,
     default_issue_status TEXT NOT NULL DEFAULT 'backlog',
     allow_public_projects INTEGER NOT NULL DEFAULT 0,
     bucket_key TEXT NOT NULL,
     tokens INTEGER NOT NULL,
     refilled_at TEXT NOT NULL
   )`,
  `CREATE INDEX IF NOT EXISTS rate_limit_org_key_idx ON rate_limit_buckets (org_id, bucket_key)`,
  `CREATE TABLE IF NOT EXISTS search_index (
     id TEXT PRIMARY KEY NOT NULL,
     org_id TEXT NOT NULL,
     subject_kind TEXT NOT NULL,
     subject_id TEXT NOT NULL,
     project_id TEXT,
     content TEXT NOT NULL,
     indexed_at TEXT NOT NULL
   )`,
  `CREATE INDEX IF NOT EXISTS search_index_org_kind_idx ON search_index (org_id, subject_kind)`,
];

/**
 * Brings `databasePath` up to date. Generated migrations win when they exist;
 * otherwise the embedded schema is pushed. Safe to run repeatedly — every
 * statement is `IF NOT EXISTS`.
 */
export async function runMigrations(
  databasePath: string = process.env.TASKFLOW_DB_PATH ?? DEFAULT_DB_PATH,
): Promise<void> {
  const absolute = resolve(process.cwd(), databasePath);
  mkdirSync(dirname(absolute), { recursive: true });

  const sqlite = new Database(absolute);
  sqlite.pragma("journal_mode = WAL");

  try {
    for (const statement of readMigrationStatements()) {
      sqlite.exec(statement);
    }
  } finally {
    sqlite.close();
  }
}

/** `pnpm db:migrate` runs this file directly; importing it must stay inert. */
if (process.argv[1]?.endsWith("migrate.ts") === true) {
  await runMigrations();
}

function readMigrationStatements(): readonly string[] {
  const dir = resolve(process.cwd(), MIGRATIONS_DIR);
  if (!existsSync(dir)) return SCHEMA_STATEMENTS;

  const files = readdirSync(dir)
    .filter((name) => name.endsWith(".sql"))
    .sort();

  if (files.length === 0) return SCHEMA_STATEMENTS;

  return files.flatMap((name) =>
    readFileSync(join(dir, name), "utf8")
      .split("--> statement-breakpoint")
      .map((chunk) => chunk.trim())
      .filter(Boolean),
  );
}
  }
}

export async function PATCH(
  request: Request,
  context: RouteContext,
): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    if (orgSlug === null) {
      return failure("validation_failed", "orgSlug is required.");
    }

    // Next.js 16: route `params` is a Promise and MUST be awaited.
    const { issueId } = await context.params;
    const actor = await getActor(orgSlug);

    const body: unknown = await request.json();
    const parsed = updateIssueSchema.safeParse({
      ...(typeof body === "object" && body !== null ? body : {}),
      orgId: actor.orgId,
      issueId,
    });
    if (!parsed.success) {
      return failure("validation_failed", "Bad issue patch.");
    }

    const current = await getIssue(actor, actor.orgId, parsed.data.issueId);
    assertOrgScope(actor, current.issue.orgId);

    const allowed = can(actor, "issue:update", {
      kind: "issue",
      orgId: current.issue.orgId,
      projectId: current.issue.projectId,
      issueId: current.issue.id,
      authorId: current.issue.authorId,
      assigneeId: current.issue.assigneeId,
    });
    if (!allowed) {
      return failure("forbidden", "You cannot update this issue.");
    }

    const updated = await updateIssue(actor, parsed.data);
    return Response.json(updated);
  } catch (error) {
    return errorResponse(error);
  }
}

