let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

it("smoke", async () => {
  const t = await createTenant("smoke", "growth");
  const other = await createTenant("smoke-other", "growth");
  const m = (await memberRepo.findMember(t.org.id, t.userIds.member))!;
  await memberRepo.insertMember(other.org.id, t.userIds.member, "member", null);
  const otherIssue = await issueService.createIssue(other.actors.owner, issueInput(other.org.id, other.project.id, { assigneeId: t.userIds.member }));
  const issue = await issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.member }));
  const proj = await projectService.updateProject(t.actors.owner, { orgId: t.org.id, projectId: t.project.id, leadId: t.userIds.member });
  expect(proj.leadId).toBe(t.userIds.member);
  await prefRepo.upsertPreference({ orgId: t.org.id, userId: t.userIds.member, kind: "comment_created", inApp: true, email: true, digestOnly: true } as never);
  expect(await listDigestRecipients(t.org.id)).toEqual([t.userIds.member]);

  await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: m.id });
  expect((await issueRepo.findIssueById(t.org.id, issue.id))!.assigneeId).toBeNull();
  expect((await issueRepo.findIssueById(other.org.id, otherIssue.id))!.assigneeId).toBe(t.userIds.member);
  expect((await projectRepo.findProjectById(t.org.id, t.project.id))!.leadId).toBeNull();
  expect(await memberService.resolveActor(t.userIds.member, t.org.id)).toBeNull();
  expect(await memberService.resolveActor(t.userIds.member, other.org.id)).not.toBeNull();
  await expect(switchActiveOrg({ userId: t.userIds.member } as never, { orgId: t.org.id })).rejects.toThrow();
  expect(await listDigestRecipients(t.org.id)).toEqual([]);
  expect(await notify(t.org.id, "issue_assigned", [t.userIds.member], { title: "x", body: "y", href: "/", actorId: null })).toEqual([]);
  await expect(memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: m.id })).rejects.toBeInstanceOf(AlreadyArchivedError);
  await expect(memberService.updateMemberRole(t.actors.owner, { orgId: t.org.id, memberId: m.id, role: "admin" })).rejects.toBeInstanceOf(AlreadyArchivedError);
  await expect(issueService.assignIssue(t.actors.owner, { orgId: t.org.id, issueId: issue.id, assigneeId: t.userIds.member })).rejects.toBeInstanceOf(NotAMemberError);
  await expect(issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { assigneeId: other.userIds.admin }))).rejects.toBeInstanceOf(NotAMemberError);
  await expect(projectService.updateProject(t.actors.owner, { orgId: t.org.id, projectId: t.project.id, name: "nope", leadId: t.userIds.member })).rejects.toBeInstanceOf(NotAMemberError);
  expect((await projectRepo.findProjectById(t.org.id, t.project.id))!.name).not.toBe("nope");

  const seats = await memberRepo.countActiveMembers(t.org.id);
  const tok = "z".repeat(32);
  const inv = await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "x@y.test", role: "admin", expiresInDays: 14 }, t.userIds.owner, hashToken(tok));
  const back = await invitationService.acceptInvitation(t.userIds.member, { token: tok });
  expect(back).toMatchObject({ id: m.id, role: "admin", status: "active", archivedAt: null, invitedBy: t.userIds.owner, createdAt: m.createdAt });
  expect(await memberRepo.countActiveMembers(t.org.id)).toBe(seats + 1);
  expect(await invitationRepo.listPendingInvitations(t.org.id)).toEqual([]);
  expect(await memberService.resolveActor(t.userIds.member, t.org.id)).toMatchObject({ role: "admin" });
  await expect(invitationService.acceptInvitation(t.userIds.member, { token: tok })).rejects.toThrow(/already been accepted/);
  expect(await listDigestRecipients(t.org.id)).toEqual([t.userIds.member]);

  const tok2 = "y".repeat(32);
  await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "x@y.test", role: "viewer", expiresInDays: 14 }, t.userIds.owner, hashToken(tok2));
  const same = await invitationService.acceptInvitation(t.userIds.member, { token: tok2 });
  expect(same.role).toBe("admin");
  expect(await invitationRepo.listPendingInvitations(t.org.id)).toEqual([]);
  expect(inv.id).toBeTruthy();
